const int N = 1e6 + 7;


ll pw(ll x, ll k, ll m = mod){
    if (!k) return 1 % m;
    if (k & 1) return x * pw(x, k - 1, m) % m;
    ll t = pw(x, k / 2, m);
    return t * t % m;
}


ll get(ll x, ll k, ll n){
    if (!k) return 1 % n;
    if (k & 1) return x * get(x, k - 1, n) % n;
    ll t = get(x, k >> 1, n);
    return t * t % n;
