void solve() {
    cin >> n >> k;

    // The problem is about counting functions f: Z_p -> Z_p such that f(x^k mod p) = f(x)^k mod p
    // For prime p, the multiplicative group Z_p* is cyclic of order p-1
    // We need to consider the functional equation f(x^k) = f(x)^k

